import logging
from taf.internal.managedobject import ManagedObject
from taf.internal.portforwarding.network import Address


logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class RemoteService(ManagedObject):

    def __init__(self, ip=None, port=None, **kwargs):
        super(RemoteService, self).__init__(**kwargs)

        self.address = Address(host=ip, port=port)


class StartableRemoteService(RemoteService):

    def __init__(self, **kwargs):
        super(StartableRemoteService, self).__init__(**kwargs)
        self._executor = None

    def attach_executor(self, executor):
        self._executor = executor


class StartableNetcatRemoteService(StartableRemoteService):

    def __init__(self,
                 netcat_reverse_server,
                 **kwargs):
        super(StartableNetcatRemoteService, self).__init__(**kwargs)

        self._netcat_reverse_server = netcat_reverse_server
        self.add_prerequisite(self._netcat_reverse_server)

    def attach_executor(self, executor):
        self._netcat_reverse_server.attach_executor(executor)


class StartableKubectlForwardRemoteService(StartableRemoteService):

    def __init__(self,
                 kubectl_portforward,
                 **kwargs):
        super(StartableKubectlForwardRemoteService, self).__init__(**kwargs)

        self._kubectl_portforward = kubectl_portforward
        self.add_prerequisite(self._kubectl_portforward)

    def attach_executor(self, executor):
        super(StartableKubectlForwardRemoteService, self).attach_executor(executor)
        self._kubectl_portforward.attach_executor(self._executor)

    def _setup(self):
        self.address.host = self._executor.ssh_connection.host
        self.address.port = self._kubectl_portforward.bind_port
